package main

import (
	"encoding/json"
	"path"
	"slices"
	"strings"
)

// hashedPaths are the repository paths of one grammar pin that can change the generated module: the pinned dirs and
// files (pins.json; files are relative to grammarDir), grammar.js, queries and the LICENSE/NOTICE texts that are hashed.
// Anything else in a commit range (docs, tests, dev scripts, CI) leaves the generated bytes alone.
// shortcut: package.json and tree-sitter.json count as docs here although npmDependencies read them; add them when a
// pin's dependency bump ever hides behind a docs-only report.
type hashedPaths struct{ dirs, files []string }

// loadHashed reads the hashed paths of every grammar. It is optional metadata like the patch records: a file it cannot
// read, or a grammar without dirs and files, gets no entry, and pinBehind then warns as it did without the filter.
func loadHashed(raw []byte) map[string]hashedPaths {
	var p struct {
		Grammars map[string]struct {
			GrammarDir string            `json:"grammarDir"`
			Dirs       []string          `json:"dirs"`
			Files      map[string]string `json:"files"`
		} `json:"grammars"`
	}
	if json.Unmarshal(raw, &p) != nil {
		return nil
	}
	out := map[string]hashedPaths{}
	for n, g := range p.Grammars {
		if len(g.Dirs) == 0 && len(g.Files) == 0 {
			continue
		}
		h := hashedPaths{dirs: g.Dirs}
		for f := range g.Files {
			h.files = append(h.files, path.Join(g.GrammarDir, f))
		}
		out[n] = h
	}
	return out
}

// affects reports whether a changed file can alter the generated module.
func (h hashedPaths) affects(file string) bool {
	if path.Base(file) == "grammar.js" || file == "LICENSE" || file == "NOTICE" ||
		strings.HasPrefix(file, "queries/") || strings.Contains(file, "/queries/") || slices.Contains(h.files, file) {
		return true
	}
	return slices.ContainsFunc(h.dirs, func(d string) bool {
		return d == "." || file == d || strings.HasPrefix(file, strings.TrimSuffix(d, "/")+"/")
	})
}

// compareFile is one entry of the compare API's file list (the net change from the pin to the head).
type compareFile struct {
	Name string `json:"filename"`
	Prev string `json:"previous_filename"`
}

// compareFileLimit is the size at which the compare API truncates its file list (300 files): the list is then unusable.
const compareFileLimit = 300

// docsOnly is true when the file list is complete, not empty and holds no path that affects the module (a rename
// counts by both names). An empty or truncated list is no proof, so the caller warns.
func (h hashedPaths) docsOnly(files []compareFile) bool {
	if len(files) == 0 || len(files) >= compareFileLimit {
		return false
	}
	return !slices.ContainsFunc(files, func(f compareFile) bool { return h.affects(f.Name) || f.Prev != "" && h.affects(f.Prev) })
}
